// Package rig loads, validates and builds layered sprite rigs.
//
// A rig directory is the single source of truth for a layered character:
//
//	rig.yml    layers, colour slots (key ramps), palettes, defaults, outputs
//	poses.yml  ordered poses: which part each layer uses, offsets, anchors
//	clips.yml  animations as {pose, ms} steps, idle behaviour, state mapping
//	parts/<layer>/<variant>/<part>.png   16x16 parts using only rig colours
//
// Everything under the outputs paths is generated by Build and must never be
// edited by hand.
package rig

import (
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

// Rig is a fully loaded rig directory.
type Rig struct {
	Dir   string
	Spec  RigSpec
	Poses []Pose
	Clips ClipsSpec
}

// RigSpec is rig.yml.
type RigSpec struct {
	Name      string `yaml:"name"`
	FrameSize int    `yaml:"frameSize"`
	Columns   int    `yaml:"columns"`
	// Layers in draw order, bottom first.
	Layers []LayerSpec `yaml:"layers"`
	// Slots are recolourable key ramps, dark to light, as #rrggbb.
	Slots map[string][]string `yaml:"slots"`
	// SlotOrder fixes iteration order for deterministic output.
	SlotOrder []string `yaml:"slotOrder"`
	// Fixed colours are allowed in parts but never recoloured (outline, eyes).
	Fixed []string `yaml:"fixed"`
	// Palettes[slot][name] is a replacement ramp the same length as the slot.
	Palettes map[string]map[string][]string `yaml:"palettes"`
	// Hidden[slot] lists palettes that only data uses (a mannequin's grey
	// skin): never picked for a new player's random look, nor offered.
	Hidden   map[string][]string `yaml:"hidden,omitempty"`
	Defaults Defaults            `yaml:"defaults"`
	Outputs  Outputs                        `yaml:"outputs"`
	// Hitbox is the collision box [x, y, w, h] within the 16px cell the
	// character stands in (its feet), not the frame: an adult drawn taller
	// still collides with the same footprint. It should hug the visible
	// body so walls are touched, not stopped short of. Default: the cell.
	Hitbox *[4]int `yaml:"hitbox,omitempty"`
	// Size is the character size this rig draws: "child" (16px frames) or
	// "adult" (taller). Appearances name the rig they use by its size.
	Size string `yaml:"size"`
	// Anchor is the point in the frame that sits on the bottom centre of the
	// character's 16px cell (its feet). Default: [frameSize/2, frameSize].
	Anchor *[2]int `yaml:"anchor,omitempty"`
}

// CellSize is the world grid cell a character stands in.
const CellSize = 16

// AnchorOrDefault returns the anchor, or the bottom centre of the frame.
func (s RigSpec) AnchorOrDefault() [2]int {
	if s.Anchor != nil {
		return *s.Anchor
	}
	return [2]int{s.FrameSize / 2, s.FrameSize}
}

// HitboxOrDefault returns the hitbox, or the whole cell.
func (s RigSpec) HitboxOrDefault() [4]int {
	if s.Hitbox != nil {
		return *s.Hitbox
	}
	return [4]int{0, 0, CellSize, CellSize}
}

// LayerSpec is one draw layer. Variants are alternative part sets (for example
// hairstyles); the first variant is the default.
type LayerSpec struct {
	Name     string   `yaml:"name"`
	Variants []string `yaml:"variants"`
}

// Defaults is the look used for the composite sheet and new players.
type Defaults struct {
	Palettes map[string]string `yaml:"palettes" json:"palettes"`
	Parts    map[string]string `yaml:"parts" json:"parts"`
}

// Outputs are paths relative to the rig directory.
type Outputs struct {
	// SheetsDir receives <layer>_<variant>.png and <name>.rig.json.
	SheetsDir string `yaml:"sheetsDir"`
	// Composite is the default-look sheet referenced by Tsx.
	Composite string `yaml:"composite"`
	// Tsx is the generated Tiled tileset the server reads entity states from.
	Tsx string `yaml:"tsx"`
	// WebRoot is the directory served as /res (paths in rig.json are relative to it).
	WebRoot string `yaml:"webRoot"`
}

// Pose is one frame of the rig: a part per layer, placed with an offset.
type Pose struct {
	Name    string            `yaml:"name"`
	Parts   map[string]string `yaml:"parts"`
	Offsets map[string][2]int `yaml:"offsets,omitempty"`
	// Hand is the held-item anchor in frame pixels; nil means no item drawn.
	Hand  *[2]int `yaml:"hand,omitempty"`
	ItemZ string  `yaml:"itemZ,omitempty"` // "front" (default) or "behind"
}

type posesFile struct {
	Poses []Pose `yaml:"poses"`
}

// Step is one timed pose inside a clip.
type Step struct {
	Pose string `yaml:"pose" json:"pose"`
	Ms   int    `yaml:"ms" json:"ms"`
}

// IdleSpec describes the idle behaviour: loop Base, occasionally play a
// weighted random variant once, then return to Base.
type IdleSpec struct {
	Base       string        `yaml:"base" json:"base"`
	Variants   []IdleVariant `yaml:"variants" json:"variants"`
	IntervalMs [2]int        `yaml:"intervalMs" json:"intervalMs"`
}

// IdleVariant is a weighted one-shot idle clip.
type IdleVariant struct {
	Clip   string `yaml:"clip" json:"clip"`
	Weight int    `yaml:"weight" json:"weight"`
}

// ClipsSpec is clips.yml.
type ClipsSpec struct {
	Clips map[string][]Step `yaml:"clips"`
	Idle  IdleSpec          `yaml:"idle"`
	// States maps entity state names (server/entdef) to clips.
	States map[string]string `yaml:"states"`
	// InitialState is the entdef's initial state (tile type "<name>").
	InitialState string `yaml:"initialState"`
}

// Load reads a rig directory.
func Load(dir string) (*Rig, error) {
	r := &Rig{Dir: dir}
	if err := readYAML(filepath.Join(dir, "rig.yml"), &r.Spec); err != nil {
		return nil, err
	}
	var pf posesFile
	if err := readYAML(filepath.Join(dir, "poses.yml"), &pf); err != nil {
		return nil, err
	}
	r.Poses = pf.Poses
	if err := readYAML(filepath.Join(dir, "clips.yml"), &r.Clips); err != nil {
		return nil, err
	}
	if r.Spec.FrameSize == 0 {
		r.Spec.FrameSize = 16
	}
	if r.Spec.Columns == 0 {
		r.Spec.Columns = 8
	}
	return r, nil
}

func readYAML(path string, out any) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if err := yaml.Unmarshal(data, out); err != nil {
		return fmt.Errorf("%s: %w", path, err)
	}
	return nil
}

// PoseIndex returns the frame index of each pose by name.
func (r *Rig) PoseIndex() map[string]int {
	idx := make(map[string]int, len(r.Poses))
	for i, p := range r.Poses {
		idx[p.Name] = i
	}
	return idx
}

// Layer returns the named layer spec.
func (r *Rig) Layer(name string) (LayerSpec, bool) {
	for _, l := range r.Spec.Layers {
		if l.Name == name {
			return l, true
		}
	}
	return LayerSpec{}, false
}

// PartPath is where a part PNG lives.
func (r *Rig) PartPath(layer, variant, part string) string {
	return filepath.Join(r.Dir, "parts", layer, variant, part+".png")
}

// DefaultVariant is the variant used for a layer in the default look.
func (r *Rig) DefaultVariant(l LayerSpec) string {
	if v, ok := r.Spec.Defaults.Parts[l.Name]; ok && v != "" {
		return v
	}
	if len(l.Variants) > 0 {
		return l.Variants[0]
	}
	return "default"
}

// LayerVariants returns the layer's variants, or ["default"].
func LayerVariants(l LayerSpec) []string {
	if len(l.Variants) == 0 {
		return []string{"default"}
	}
	return l.Variants
}
